    22 => LOK_CALLBACK_ERROR,
    23 => LOK_CALLBACK_CONTEXT_MENU,
    24 => LOK_CALLBACK_INVALIDATE_VIEW_CURSOR,
    25 => LOK_CALLBACK_TEXT_VIEW_SELECTION,
    26 => LOK_CALLBACK_CELL_VIEW_CURSOR,
    27 => LOK_CALLBACK_GRAPHIC_VIEW_SELECTION,
    28 => LOK_CALLBACK_VIEW_CURSOR_VISIBLE,
    29 => LOK_CALLBACK_VIEW_LOCK,
    30 => LOK_CALLBACK_REDLINE_TABLE_SIZE_CHANGED,
    31 => LOK_CALLBACK_REDLINE_TABLE_ENTRY_MODIFIED,
    32 => LOK_CALLBACK_COMMENT,
    33 => LOK_CALLBACK_INVALIDATE_HEADER,
    34 => LOK_CALLBACK_CELL_ADDRESS,
    35 => LOK_CALLBACK_RULER_UPDATE,
    36 => LOK_CALLBACK_WINDOW,
    37 => LOK_CALLBACK_VALIDITY_LIST_BUTTON,
